mapper.select:
select hlcre.*,hdbs.description date_source_desc,hret.description ruleEngineTypeDesc
from hls_layout_code_rule_engine hlcre
left join hls_rule_engine_type hret on hret.rule_engine_type = hlcre.rule_engine_type
left join hls_db_data_source hdbs on hlcre.data_source_id = hdbs.data_source_id


        and hlcre.layout_code_engine_code = #{layoutCodeEngineCode}


        and hlcre.layout_code_engine_name = #{layoutCodeEngineName}


        and hlcre.enabled_flag = #{enabledFlag}


order by
hlcre.sequence asc
